//! Every case the property tests have shrunk to so far (from the comments of
//! tests/fuzz.proptest-regressions and the cases left open after the
//! 24-seed run), as plain tests: emulator A gets the program, a fresh
//! emulator B gets A's redraw, then both get the suffix. The redraw must
//! never panic and must stay within its bound; where A's state is one a
//! redraw can reproduce (`Snapshot::layout_reproducible`), B must match A
//! before and after the suffix, with no masking beyond what `diff` names.
//! Collected by the architecture review (review-term-tree/open_unmasked.rs).

use ssh3_term::{max_resync_len, Screen};

fn check(mut a: Screen, suffix: &[u8]) {
    let (c, r) = a.size();
    let redraw = a.resync();
    assert!(redraw.len() <= max_resync_len(c, r), "redraw {} > bound", redraw.len());
    let mut b = Screen::new(c, r);
    b.feed(&redraw);
    let snap = a.snapshot();
    if snap.irreproducible().is_some() {
        return;
    }
    let (rep, wrap) = (snap.rep_reproducible(), snap.wrap_reproducible());
    let before = snap.diff(&b.snapshot());
    assert!(before.is_empty(), "after redraw: {before:#?}");
    if !wrap {
        return;
    }
    a.feed(suffix);
    b.feed(suffix);
    let after = a.snapshot().diff_with(&b.snapshot(), rep);
    assert!(after.is_empty(), "after suffix: {after:#?}");
}
